INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c5040000-0000-4000-8000-000000000001', 'c5030000-0000-4000-8000-000000000001', 1, 'TEXT', 'Đọc lướt (skimming) là đọc nhanh để biết mỗi đoạn nói về gì. Hãy đọc kỹ câu đầu, liếc qua các câu giữa và chú ý từ khóa lặp lại. Mỗi đoạn thường có một ý chính: đoạn A giới thiệu, đoạn B mở rộng, đoạn C nêu vấn đề hoặc kết luận. Từ như "however", "but" báo hiệu đoạn văn đổi hướng. Viết vài chữ bên lề cho ý mỗi đoạn trước khi trả lời câu hỏi.');
