INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c5040000-0000-4000-8000-000000000004', 'c5030000-0000-4000-8000-000000000002', 1, 'TEXT', 'Câu hỏi trả lời ngắn yêu cầu bạn chép từ trong bài, ví dụ "NO MORE THAN TWO WORDS". Gạch chân từ khóa trong câu hỏi, tìm từ đó hoặc từ đồng nghĩa trong bài, rồi đọc kỹ câu chứa nó. Chép đúng chính tả, không đổi dạng từ, và đếm số từ. Con số viết bằng chữ số được tính là một từ.');
