INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c5040000-0000-4000-8000-000000000013', 'c5030000-0000-4000-8000-000000000005', 1, 'TEXT', 'Mạo từ: dùng "a/an" với danh từ đếm được số ít nhắc lần đầu, "the" khi người đọc đã biết vật đó hoặc chỉ có một (the sun). Danh từ không đếm được (information, advice) không dùng "a" và không thêm -s. Hòa hợp chủ ngữ – động từ: động từ theo chủ ngữ chính, không theo danh từ gần nhất. "The number of students is rising" (chủ ngữ là "number"), còn "A number of students are late". "Everyone", "each" đi với động từ số ít.');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('c5040000-0000-4000-8000-000000000013', (SELECT id FROM knowledge_points WHERE code = 'G55_ARTICLES'));
