INSERT INTO lessons (id, topic_id, code, title, sort_order, status, estimated_minutes) VALUES ('c5030000-0000-4000-8000-000000000006', (SELECT id FROM topics WHERE code = 'IELTS_5_0_GRAMMAR'), 'G50-2', 'So sánh và câu bị động', 2, 'PUBLISHED', 10);
