INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c5040000-0000-4000-8000-000000000015', 'c5030000-0000-4000-8000-000000000006', 1, 'TEXT', 'So sánh hơn: tính từ ngắn thêm -er (cheaper), tính từ dài dùng "more" (more expensive), kèm "than". So sánh nhất: "the cheapest", "the most expensive". Bất quy tắc: good – better – best, bad – worse – worst. Câu bị động dùng "be + quá khứ phân từ" khi người làm không quan trọng: "The bridge was built in 1990." Bị động rất hay gặp khi mô tả quy trình và số liệu trong Writing Task 1.');
