INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c5040000-0000-4000-8000-000000000017', 'c5030000-0000-4000-8000-000000000007', 1, 'TEXT', 'Từ nối chỉ quan hệ giữa các ý: thêm ý (also, in addition), đối lập (but, however), nguyên nhân (because, since), kết quả (so, therefore). "However" và "therefore" thường đứng đầu câu, sau đó là dấu phẩy. Câu phức gồm một mệnh đề chính và một mệnh đề phụ bắt đầu bằng although, because, when, if: "Although it was raining, we went out." Mệnh đề phụ không đứng một mình thành câu.');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('c5040000-0000-4000-8000-000000000017', (SELECT id FROM knowledge_points WHERE code = 'G55_LINKING_WORDS'));
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('c5040000-0000-4000-8000-000000000017', (SELECT id FROM knowledge_points WHERE code = 'G55_COMPLEX_SENTENCES'));
INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type) VALUES ('c5040000-0000-4000-8000-000000000018', 'c5030000-0000-4000-8000-000000000007', 2, 'EXERCISE');
INSERT INTO questions (id, question_type, skill, purpose, status) VALUES ('c5060000-0000-4000-8000-000000000061', 'MULTIPLE_CHOICE', 'WRITING', 'LEARNING', 'PUBLISHED');
INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('c5070000-0000-4000-8000-000000000061', 'c5060000-0000-4000-8000-000000000061', 1, 'Choose the best linking word: The hotel was expensive. ______, it was very comfortable.', '[{"optionKey": "A", "content": "Therefore", "sortOrder": 1}, {"optionKey": "B", "content": "However", "sortOrder": 2}, {"optionKey": "C", "content": "Because", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "B"}', 1, 'However shows contrast between expensive and comfortable.', 'EASY', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('c5070000-0000-4000-8000-000000000061', (SELECT id FROM knowledge_points WHERE code = 'G55_LINKING_WORDS'), 1.0);
INSERT INTO lesson_block_questions (block_id, question_version_id, sort_order) VALUES ('c5040000-0000-4000-8000-000000000018', 'c5070000-0000-4000-8000-000000000061', 1);
INSERT INTO questions (id, question_type, skill, purpose, status) VALUES ('c5060000-0000-4000-8000-000000000062', 'MULTIPLE_CHOICE', 'WRITING', 'LEARNING', 'PUBLISHED');
