INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c5040000-0000-4000-8000-000000000019', 'c5030000-0000-4000-8000-000000000008', 1, 'TEXT', 'Mệnh đề quan hệ bổ sung thông tin cho danh từ: "who" cho người, "which" cho vật, "where" cho nơi chốn, "whose" chỉ sở hữu. "That" thay được cho who/which trong mệnh đề xác định. "The teacher who helped me is retired." Khi mệnh đề chỉ thêm thông tin phụ, đặt nó giữa hai dấu phẩy và không dùng "that": "Hue, which is in central Vietnam, is famous for its old citadel."');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('c5040000-0000-4000-8000-000000000019', (SELECT id FROM knowledge_points WHERE code = 'G55_RELATIVE_CLAUSES'));
