INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c5040000-0000-4000-8000-000000000021', 'c5030000-0000-4000-8000-000000000009', 1, 'TEXT', 'Các chủ đề IELTS hay gặp: giáo dục, môi trường, công nghệ, sức khỏe, công việc. Học từ theo chủ đề: môi trường có pollution, recycle, renewable energy. Mỗi từ có nhiều dạng: danh từ (development), động từ (develop), tính từ (developed), trạng từ. Chọn dạng theo vị trí: sau "the" cần danh từ, trước danh từ cần tính từ, sau động từ thường cần trạng từ.');
