INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c5040000-0000-4000-8000-000000000023', 'c5030000-0000-4000-8000-000000000010', 1, 'TEXT', 'Collocation là các từ hay đi cùng nhau: "make a decision" (không nói "do a decision"), "play a role", "have an impact on", "raise awareness". Dùng đúng collocation làm bài viết tự nhiên hơn. Diễn đạt lại (paraphrase) là nói cùng ý bằng từ khác: "increase" = "rise" = "grow", "important" = "essential", "people" = "individuals". IELTS thường paraphrase từ trong câu hỏi, nên học từ đồng nghĩa giúp bạn tìm đáp án nhanh hơn.');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('c5040000-0000-4000-8000-000000000023', (SELECT id FROM knowledge_points WHERE code = 'V55_ACADEMIC_COLLOCATIONS'));
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('c5040000-0000-4000-8000-000000000023', (SELECT id FROM knowledge_points WHERE code = 'V55_PARAPHRASE_WORDS'));
