INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c5040000-0000-4000-8000-000000000025', 'c5030000-0000-4000-8000-000000000011', 1, 'TEXT', 'Câu ghép nối hai mệnh đề độc lập bằng liên từ and (thêm), but (đối lập), so (kết quả), or (lựa chọn). Đặt dấu phẩy trước liên từ khi hai mệnh đề đều dài: "The city is crowded, but it offers many jobs." Không nối hai câu chỉ bằng dấu phẩy ("The city is crowded, it offers many jobs" là sai). Câu ghép giúp bài viết bớt rời rạc so với nhiều câu đơn ngắn.');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('c5040000-0000-4000-8000-000000000025', (SELECT id FROM knowledge_points WHERE code = 'W50_COMPOUND_SENTENCES'));
