INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('c5040000-0000-4000-8000-000000000027', 'c5030000-0000-4000-8000-000000000012', 1, 'TEXT', 'Đoạn nêu ý kiến bắt đầu bằng câu chủ đề nói rõ quan điểm: "In my opinion, students should learn to cook at school." Tiếp theo là hai lý do, mỗi lý do kèm ví dụ hoặc giải thích, nối bằng "Firstly", "In addition", "For example". Câu kết nhắc lại quan điểm bằng cách khác. Dùng câu ghép và câu phức để nối ý, nhưng mỗi câu chỉ nên mang một ý chính.');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('c5040000-0000-4000-8000-000000000027', (SELECT id FROM knowledge_points WHERE code = 'W50_OPINION_PARAGRAPH'));
