INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('c5070000-0000-4000-8000-000000000111', 'c5060000-0000-4000-8000-000000000111', 1, 'Which is the clearest opinion topic sentence?', '[{"optionKey": "A", "content": "Some people cook.", "sortOrder": 1}, {"optionKey": "B", "content": "In my view, every student should learn to cook.", "sortOrder": 2}, {"optionKey": "C", "content": "Cooking was invented long ago.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "B"}', 1, 'It states the writer''s position clearly.', 'EASY', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('c5070000-0000-4000-8000-000000000111', (SELECT id FROM knowledge_points WHERE code = 'W50_OPINION_PARAGRAPH'), 1.0);
