INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('c5070000-0000-4000-8000-000000000112', 'c5060000-0000-4000-8000-000000000112', 1, 'Which sentence best supports the opinion ''Public transport should be free''?', '[{"optionKey": "A", "content": "For example, free buses would encourage people to leave their cars at home.", "sortOrder": 1}, {"optionKey": "B", "content": "Buses are usually red.", "sortOrder": 2}, {"optionKey": "C", "content": "I took a taxi last week.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A"}', 1, 'It gives a reason with a concrete effect.', 'MEDIUM', 'PUBLISHED');
